for name, lessons in [('maths', maths), ('science', science), ('english', english)]:
    with open(f'{OUT}/{name}.json', 'w') as f:
        json.dump({'subject': name, 'version': 1, 'lessons': lessons}, f, indent=1, ensure_ascii=False)
    print(name, len(lessons))
